import { useEffect, useState } from "react";
import styled from "styled-components";
import { collection, getDocs } from "firebase/firestore";
import { db } from "../services/firebaseConfig";
import { BarChart, Bar, XAxis, YAxis, Tooltip, Legend, ResponsiveContainer } from "recharts";

const Container = styled.div`
  padding: 2rem;
  text-align: center;
`;

const SummaryBox = styled.div`
  display: flex;
  justify-content: space-around;
  gap: 1rem;
  margin-bottom: 2rem;
`;

const Card = styled.div`
  background: #151c2e;
  padding: 1.5rem;
  border-radius: 16px;
  flex: 1;
  box-shadow: 0px 4px 12px rgba(0,0,0,0.2);
`;

const CardTitle = styled.h3`
  color: #00c98d;
  margin-bottom: 0.5rem;
`;

const CardValue = styled.p`
  font-size: 1.5rem;
  font-weight: bold;
`;

export default function Dashboard() {
  const [transactions, setTransactions] = useState([]);
  const [chartData, setChartData] = useState([]);

  useEffect(() => {
    const fetchData = async () => {
      const querySnapshot = await getDocs(collection(db, "transactions"));
      const data = querySnapshot.docs.map(doc => doc.data());
      setTransactions(data);

      // Agrupar por categoria e tipo
      const categories = [...new Set(data.map(t => t.category))];
      const chartArr = categories.map(cat => {
        const entrada = data
          .filter(t => t.category === cat && t.type === "Entrada")
          .reduce((acc, t) => acc + t.value, 0);
        const saida = data
          .filter(t => t.category === cat && t.type === "Saída")
          .reduce((acc, t) => acc + t.value, 0);
        return { category: cat, Entrada: entrada, Saída: saida };
      });
      setChartData(chartArr);
    };
    fetchData();
  }, []);

  const totalEntradas = transactions
    .filter(t => t.type === "Entrada")
    .reduce((acc, t) => acc + t.value, 0);

  const totalSaidas = transactions
    .filter(t => t.type === "Saída")
    .reduce((acc, t) => acc + t.value, 0);

  const saldo = totalEntradas - totalSaidas;

  return (
    <Container>
      <h1>Resumo Financeiro</h1>

      <SummaryBox>
        <Card>
          <CardTitle>Entradas</CardTitle>
          <CardValue>R$ {totalEntradas}</CardValue>
        </Card>

        <Card>
          <CardTitle>Saídas</CardTitle>
          <CardValue>R$ {totalSaidas}</CardValue>
        </Card>

        <Card>
          <CardTitle>Saldo</CardTitle>
          <CardValue>R$ {saldo}</CardValue>
        </Card>
      </SummaryBox>

      <h2>Entradas x Saídas por Categoria</h2>
      {chartData.length > 0 ? (
        <ResponsiveContainer width="100%" height={400}>
          <BarChart data={chartData} margin={{ top: 20, right: 30, left: 0, bottom: 5 }}>
            <XAxis dataKey="category" stroke="#fff" />
            <YAxis stroke="#fff" />
            <Tooltip />
            <Legend />
            <Bar dataKey="Entrada" fill="#00c98d" />
            <Bar dataKey="Saída" fill="#ff4c60" />
          </BarChart>
        </ResponsiveContainer>
      ) : (
        <p>Nenhuma transação para mostrar no gráfico.</p>
      )}
    </Container>
  );
}
